import { readFile } from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

import { expect, type Page, test } from '@playwright/test'

import { uploadFixture } from '../helpers/fileUpload'

const currentDir = path.dirname(fileURLToPath(import.meta.url))
const samples = path.resolve(
  currentDir,
  '../../../../resources/cad-data/samples'
)
// Generated by tools/make-dwg-sample.mjs; also served as a demo sample.
const dwgSamplePath = path.join(samples, 'dwg-sample.dwg')

/** Main menu (≡) of the top bar > Export > label. */
async function openExport(page: Page, label: string) {
  await page.getByTestId('top-bar-menu').click()
  const menus = page.locator('.ml-context-menu')
  await menus.getByText('Export', { exact: true }).first().hover()
  await menus.getByText(label, { exact: true }).first().click()
}

/** Picks a version in the export dialog's version list. */
async function pickVersion(page: Page, label: string) {
  await page.getByTestId('export-version').click()
  await page.getByRole('option', { name: label, exact: true }).click()
}

async function download(page: Page) {
  const pending = page.waitForEvent('download')
  await page.getByRole('button', { name: 'OK' }).click()
  const file = await pending
  return {
    name: file.suggestedFilename(),
    bytes: await readFile(await file.path())
  }
}

test('opens a DWG drawing through the acadrust worker', async ({ page }) => {
  const pageErrors: string[] = []
  page.on('pageerror', error => pageErrors.push(error.message))
  const requested: string[] = []
  page.on('request', request => requested.push(request.url()))
  const wasmResponse = page.waitForResponse(response =>
    response.url().endsWith('/acadrust-engine.wasm')
  )

  await page.goto('/')
  await uploadFixture(page, dwgSamplePath)

  expect((await wasmResponse).ok()).toBeTruthy()
  await expect(page.locator('.ml-cad-container canvas').first()).toBeVisible()
  await expect(page.getByText('dwg-sample.dwg').first()).toBeVisible()
  await expect(page.getByText(/Failed to open/)).toHaveCount(0)
  expect(pageErrors).toEqual([])
  // No trace of the GPL parser this replaced.
  expect(requested.filter(url => /libredwg/i.test(url))).toEqual([])
})

test('does not load the DWG engine for a DXF drawing', async ({ page }) => {
  const requested: string[] = []
  page.on('request', request => requested.push(request.url()))

  await page.goto('/')
  await uploadFixture(page, path.join(samples, 'sjis-sample.dxf'))
  await expect(page.getByText('sjis-sample.dxf').first()).toBeVisible()
  await expect(page.getByText(/Failed to open/)).toHaveCount(0)

  // The converter's small glue module is part of the app; its worker and the
  // 6.5 MB engine are only fetched when a DWG is opened or written.
  expect(
    requested.filter(url => /acadrust-(worker\.js|engine\.wasm)/.test(url))
  ).toEqual([])
})

test('reads a DXF through acadrust with ?dxf=acadrust', async ({ page }) => {
  const pageErrors: string[] = []
  page.on('pageerror', error => pageErrors.push(error.message))
  const wasmResponse = page.waitForResponse(response =>
    response.url().endsWith('/acadrust-engine.wasm')
  )

  await page.goto('/?dxf=acadrust')
  await uploadFixture(page, path.join(samples, 'sjis-sample.dxf'))

  expect((await wasmResponse).ok()).toBeTruthy()
  await expect(page.getByText('sjis-sample.dxf').first()).toBeVisible()
  await expect(page.getByText(/Failed to open/)).toHaveCount(0)
  expect(pageErrors).toEqual([])
})

test('exports a drawing as DWG and opens it again', async ({
  page
}, testInfo) => {
  const pageErrors: string[] = []
  page.on('pageerror', error => pageErrors.push(error.message))

  await page.goto('/')
  await uploadFixture(page, path.join(samples, 'jww-sample.jww'))
  await expect(page.getByText('jww-sample.jww').first()).toBeVisible()

  await openExport(page, 'Export to DWG')
  // The newest version is offered first.
  await expect(page.getByTestId('export-version')).toContainText('AutoCAD 2018')
  const file = await download(page)
  expect(file.name).toBe('jww-sample.dwg')
  expect(file.bytes.subarray(0, 6).toString('latin1')).toBe('AC1032')
  await expect(page.getByText(/Could not export/)).toHaveCount(0)

  // Open the written file in a fresh viewer.
  const target = testInfo.outputPath('exported.dwg')
  await testInfo.attach('exported.dwg', { body: file.bytes })
  const { writeFile } = await import('node:fs/promises')
  await writeFile(target, file.bytes)
  await page.goto('/')
  await uploadFixture(page, target)
  await expect(page.getByText('exported.dwg').first()).toBeVisible()
  await expect(page.getByText(/Failed to open/)).toHaveCount(0)
  expect(pageErrors).toEqual([])
})

test('exports DWG in the chosen version', async ({ page }) => {
  await page.goto('/')
  await uploadFixture(page, dwgSamplePath)
  await expect(page.getByText('dwg-sample.dwg').first()).toBeVisible()

  await openExport(page, 'Export to DWG')
  await pickVersion(page, 'AutoCAD 2000')
  const file = await download(page)
  expect(file.bytes.subarray(0, 6).toString('latin1')).toBe('AC1015')
  await expect(page.getByText(/Could not export/)).toHaveCount(0)
})

test('exports DXF in another version (R12)', async ({ page }) => {
  await page.goto('/')
  await uploadFixture(page, dwgSamplePath)
  await expect(page.getByText('dwg-sample.dwg').first()).toBeVisible()

  await openExport(page, 'Export to DXF')
  // The drawing's own version is the default; nothing changes unless asked.
  await expect(page.getByTestId('export-version')).toContainText(
    'Same as the drawing'
  )
  await pickVersion(page, 'R12')
  const file = await download(page)
  expect(file.name).toBe('dwg-sample.dxf')
  const text = file.bytes.toString('latin1')
  expect(text).toContain('AC1009')
  // Genuine R12: no subclass markers.
  expect(text).not.toContain('AcDbEntity')
  await expect(page.getByText(/Could not export/)).toHaveCount(0)
})
